package main

import (
    "fmt"
    "regexp"
)

func isValidSubdomain(subdomain string) bool {
    // Regular expression to match valid subdomain characters
    pattern := `^[a-zA-Z0-9.]+$`
    if matched, _ := regexp.MatchString(pattern, subdomain); !matched {
        return false
    }
    // Additional check to prevent DNS rebinding attacks by ensuring the subdomain doesn't end with a dot
    if subdomain[len(subdomain)-1] == '.' {
        return false
    }
    return true
}

func main() {
    // Test cases
    fmt.Println(isValidSubdomain("subdomain"))      // Expected: true
    fmt.Println(isValidSubdomain("a.b"))            // Expected: true
    fmt.Println(isValidSubdomain(""))               // Expected: false
    fmt.Println(isValidSubdomain("!invalid"))       // Expected: false
    fmt.Println(isValidSubdomain("example."))       // Expected: false (ends with dot)
}
